// src/js/App.js
import React, { useState, useEffect } from "react";
import Login from "../jsx/Login";
import Register from "../jsx/Register";
import UsersList from "../jsx/UsersList";
import PrivateChat from "../jsx/PrivateChat";
import { auth } from "./firebaseConfig";
import { onAuthStateChanged, signOut } from "firebase/auth";
import "../css/App.css";
import { doc, setDoc } from "firebase/firestore";
import { db } from "./firebase";

function App() {
    const [user, setUser] = useState(null);
    const [screen, setScreen] = useState("login"); // login | register | users
    const [activeChatUser, setActiveChatUser] = useState(null);

    useEffect(() => {
        const unsub = onAuthStateChanged(auth, (u) => {
            setUser(u);
            if (u) setScreen("users");
            else setScreen("login");
        });
        return () => unsub();
    }, []);

    const handleLogin = async () => {
        const userCredential = await signInWithEmailAndPassword(auth, email, senha);
        const user = userCredential.user;

        // Aqui você registra que o usuário está online
        await setDoc(doc(db, "usuarios", user.uid), {
            email: user.email,
            online: true,
        }, { merge: true });
    };

    const logout = async () => {
        await signOut(auth);
        setUser(null);
        setScreen("login");
    };

    if (!user) {
        if (screen === "register") return <Register setScreen={setScreen} />;
        return <Login setUser={setUser} setScreen={setScreen} />;
    }

    if (activeChatUser) {
        return <PrivateChat currentUser={user} otherUser={activeChatUser} onClose={() => setActiveChatUser(null)} />;
    }

    return (
        <div style={{ display: "flex", gap: 20, padding: 20 }}>
            <div style={{ width: 300 }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                    <h2>Olá, {user.displayName || user.email}</h2>
                    <button onClick={logout}>Sair</button>
                </div>
                <UsersList currentUser={user} openChatWith={u => setActiveChatUser(u)} />
            </div>

            <div style={{ flex: 1 }}>
                <p>Selecione um usuário para iniciar o chat privado.</p>
            </div>
        </div>
    );
}

export default App;
